code='''def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    cnt=Counter(x for row in grid for x in row)
    bg=cnt.most_common(1)[0][0]
    linecolors=set()
    for i in range(h):
        if len(set(grid[i]))==1 and grid[i][0]!=bg: linecolors.add(grid[i][0])
    for j in range(w):
        col={grid[i][j] for i in range(h)}
        if len(col)==1 and list(col)[0]!=bg: linecolors.add(list(col)[0])
    out=[row[:] for row in grid]
    for c in linecolors:
        for i in range(h):
            if grid[i][0]==c and len(set(grid[i]))==1:
                out[i]=[2]*w
        for j in range(w):
            if all(grid[i][j]==c for i in range(h)):
                for i in range(h): out[i][j]=2
    return out
'''
